use arbitrary::Unstructured;
use serde_json::Value;

/// Round-trip serialization test for a message type.
///
/// Raw-bytes mode (2 args) parses the raw input bytes and, on success, asserts that
/// re-encoding is stable, `Display` output survives the roundtrip, and a well-formed
/// unknown TLV suffix is ignored.
///
/// Generator mode (3 args) runs raw-bytes mode on the input, then turns the same input
/// into wire-valid bytes through the generator. Those bytes must parse, pass the same
/// checks, and re-encode to exactly the generated bytes. No protocol-level semantic
/// validation is performed.
#[macro_export]
macro_rules! test_roundtrip {
    // ---- checks shared by every mode, evaluates to the encoding of `$parsed` ----
    (@check $msg_type:ty, $parsed:ident) => {{
        let mut encoded_1 = vec![0u8; $parsed.get_size()];
        let written = $parsed
            .clone()
            .to_bytes(&mut encoded_1)
            .expect("Encoding failed after a successful parse");
        assert_eq!(
            written,
            $parsed.get_size(),
            "Encoded length must match get_size()"
        );

        let mut encoded_1_clone = encoded_1.clone();
        let reparsed = <$msg_type>::from_bytes(&mut encoded_1_clone)
            .expect("Roundtrip failed: serializer produced invalid bytes");

        let mut encoded_2 = vec![0u8; reparsed.get_size()];
        let written_2 = reparsed
            .clone()
            .to_bytes(&mut encoded_2)
            .expect("Second encoding failed");
        assert_eq!(
            written_2,
            reparsed.get_size(),
            "Second encoding length must match get_size()"
        );

        assert_eq!(encoded_1, encoded_2, "Serialization is not stable");
        assert!(!encoded_1.is_empty(), "Encoded output must not be empty");

        // Not all message types implement Eq, so compare Display output.
        let display = $parsed.to_string();
        assert_eq!(display, reparsed.to_string(), "Display output mismatch");

        // Spec 3.4.3: unknown TLV fields are safe to ignore. Appending a
        // well-formed TLV after a complete message must not change the decoded
        // base message or its size.
        let mut with_trailing = encoded_1.clone();
        with_trailing.extend_from_slice(&$crate::common::TRAILING_TLV);
        let with_trailing_parsed = <$msg_type>::from_bytes(&mut with_trailing).expect(concat!(
            stringify!($msg_type),
            ": well-formed unknown TLV suffix must be ignored"
        ));
        assert_eq!(
            with_trailing_parsed.to_string(),
            display,
            "{}: trailing TLV changed decoded message",
            stringify!($msg_type)
        );
        assert_eq!(
            with_trailing_parsed.get_size(),
            $parsed.get_size(),
            "{}: trailing TLV changed decoded size",
            stringify!($msg_type)
        );

        encoded_1
    }};
    // ---- raw-bytes mode ----
    ($msg_type:ty, $data:expr) => {{
        // Invalid inputs are expected in fuzzing, so ignore failures.
        let mut input = $data.clone();
        if let Ok(parsed) = <$msg_type>::from_bytes(&mut input) {
            $crate::test_roundtrip!(@check $msg_type, parsed);
        }
    }};
    // ---- generator mode: wire-valid bytes only ----
    ($msg_type:ty, $data:expr, $gen:expr) => {{
        $crate::test_roundtrip!($msg_type, $data);

        let mut u = arbitrary::Unstructured::new(&$data);
        if let Ok(generated) = $gen(&mut u) {
            let mut bytes = generated.clone();
            let parsed = <$msg_type>::from_bytes(&mut bytes).expect(concat!(
                stringify!($msg_type),
                ": generator produced unparseable bytes"
            ));
            let encoded = $crate::test_roundtrip!(@check $msg_type, parsed);
            assert_eq!(
                encoded,
                generated,
                "{}: encoding differs from the generated bytes",
                stringify!($msg_type)
            );
        }
    }};
}

#[macro_export]
macro_rules! test_datatype_roundtrip {
    // ---- checks shared by the generic and generator modes ----
    // Evaluates to the encoding of `$parsed`.
    (@check $datatype:ty, $parsed:ident) => {{
        let mut encoded = vec![0u8; $parsed.get_size()];
        let written = $parsed.clone().to_bytes(&mut encoded).expect(concat!(
            stringify!($datatype),
            ": Encoding failed after a successful parse"
        ));
        assert_eq!(
            written,
            $parsed.get_size(),
            "{}: Encoded length must match get_size()",
            stringify!($datatype)
        );

        // Serialized bytes must be parseable again into the same datatype.
        let mut encoded_clone = encoded.clone();
        let reparsed = <$datatype>::from_bytes(&mut encoded_clone).expect(concat!(
            stringify!($datatype),
            ": The bytes generated from a valid datatype should be parseable"
        ));

        // Semantic equality after roundtrip is required.
        assert_eq!(
            $parsed,
            reparsed,
            "{}: The roundtrip should produce the same message",
            stringify!($datatype)
        );

        let mut reencoded = vec![0u8; reparsed.get_size()];
        let written_2 = reparsed.clone().to_bytes(&mut reencoded).expect(concat!(
            stringify!($datatype),
            ": Second encoding failed"
        ));
        assert_eq!(
            written_2,
            reparsed.get_size(),
            "{}: Second encoding length must match get_size()",
            stringify!($datatype)
        );
        assert_eq!(
            encoded,
            reencoded,
            "{}: Serialization is not stable",
            stringify!($datatype)
        );

        // A strict prefix cannot contain enough bytes to decode the value.
        // Check that the decoder rejects it instead of fabricating a value
        // from incomplete input.
        for cut in $crate::common::prefix_cuts(encoded.len()) {
            let mut truncated = encoded[..cut].to_vec();
            assert!(
                <$datatype>::from_bytes(&mut truncated).is_err(),
                "{}: strict prefix ({} of {} bytes) decoded successfully",
                stringify!($datatype),
                cut,
                encoded.len()
            );
        }

        encoded
    }};

    // ---- special rule for bool ----
    // Bool has a non-canonical encoding in the spec: only the lowest bit is meaningful.
    // Multiple byte values can parse to the same logical bool, so we cannot require a
    // strict byte-for-byte roundtrip. Instead we check semantic stability and canonicalization.
    (bool, $data:expr) => {{
        let mut input = $data.clone();

        // Only run the roundtrip checks if parsing succeeds. Invalid inputs are ignored,
        // because this macro validates stability of valid encodings, not rejection behavior.
        if let Ok(parsed) = bool::from_bytes(&mut input) {
            // Allocate exactly the number of bytes required by the parsed value.
            // This ensures we test the canonical serialized size.
            let mut encoded = vec![0u8; parsed.get_size()];

            // A successful parse must always be serializable.
            parsed
                .to_bytes(&mut encoded)
                .expect("Bool encoding failed after a successful parse");

            // Bytes produced by serialization must always be parseable again.
            let reparsed = bool::from_bytes(&mut encoded)
                .expect("The bytes generated from a valid bool should be parseable");

            // Logical value must be preserved by parse → serialize → parse.
            assert_eq!(parsed, reparsed, "Bool roundtrip is not stable");

            // Because only the lowest bit is significant, we compare the semantic bit,
            // not the full original byte. This verifies canonical encoding.
            assert_eq!(input[0] & 1, encoded[0], "Bool serialization is not stable");
        }
    }};

    // ---- special rule for f32 ----
    // Floats require bit-level comparison IEEE-754.
    (f32, $data:expr) => {{
        let mut input = $data.clone();

        // Only validate successful parses; invalid encodings are outside this macro’s scope.
        if let Ok(parsed) = f32::from_bytes(&mut input) {
            // Allocate the exact canonical size of the float representation.
            let mut encoded = vec![0u8; parsed.get_size()];

            // A successfully parsed float must serialize without failure.
            parsed
                .to_bytes(&mut encoded)
                .expect("Encoding failed after a successful parse");

            // Serialized bytes must be parseable back into a float.
            let reparsed = f32::from_bytes(&mut encoded)
                .expect("The bytes generated from a valid datatype should be parseable");

            // Compare raw bits to enforce strict roundtrip stability, including NaN payloads.
            assert_eq!(
                parsed.to_bits(),
                reparsed.to_bits(),
                "Float roundtrip is not bit-stable"
            );

            // Ensure serialization is canonical: re-encoding must match the consumed input.
            assert_eq!(
                encoded,
                input[..encoded.len()],
                "Serialization is not stable"
            );
        }
    }};

    // ---- generic rule ----
    ($datatype:ty, $data:expr) => {{
        let mut input = $data.clone();
        let input_bytes = input.clone();

        if let Ok(parsed) = <$datatype>::from_bytes(&mut input) {
            let encoded = $crate::test_datatype_roundtrip!(@check $datatype, parsed);

            // Reserialization must match the consumed input bytes.
            assert_eq!(
                encoded,
                input_bytes[..encoded.len()],
                "{}: Serialization is not stable",
                stringify!($datatype)
            );
        }
    }};

    // ---- generator mode: generic ----
    // The generator produces wire-valid bytes. Parsing must succeed and
    // re-encoding must reproduce the generated bytes exactly.
    ($datatype:ty, $data:expr, $gen:expr) => {{
        $crate::test_datatype_roundtrip!($datatype, $data);

        let mut u = arbitrary::Unstructured::new(&$data);
        if let Ok(generated) = $gen(&mut u) {
            let mut bytes = generated.clone();
            let parsed = <$datatype>::from_bytes(&mut bytes).expect(concat!(
                stringify!($datatype),
                ": generator produced unparseable bytes"
            ));
            let encoded = $crate::test_datatype_roundtrip!(@check $datatype, parsed);
            assert_eq!(
                encoded,
                generated,
                "{}: encoding differs from the generated bytes",
                stringify!($datatype)
            );
        }
    }};
}

/// A well-formed TLV with an unallocated experimental extension type.
///
/// Per spec 3.4.3, unknown TLV fields are safe to ignore. Appending this after a
/// complete message checks that the TLV does not change the decoded base message.
///
/// Layout: extension_type = 0x4000 (U16 LE), field_type = 0x01 (U8),
/// length = 2 (U16 LE), value = `[0xAB, 0xCD]`.
#[allow(dead_code)]
pub const TRAILING_TLV: [u8; 7] = [0x00, 0x40, 0x01, 0x02, 0x00, 0xAB, 0xCD];

/// Sorted, deduplicated strict prefix cut points for a given length.
///
/// Tests empty (0), midpoint (len/2), and one-byte-short (len-1) positions.
/// Used by the datatype strict-prefix check.
#[allow(dead_code)]
pub fn prefix_cuts(len: usize) -> Vec<usize> {
    if len == 0 {
        return Vec::new();
    }
    let mut cuts = vec![len - 1, len / 2, 0];
    cuts.sort_unstable();
    cuts.dedup();
    cuts
}

/// WARNING: Generated with OpenAI's GPT-5.5 free model
///
/// Generate an arbitrary [`Value`] with bounded recursion depth.
///
/// Used by the SV1 fuzz targets (`fuzz_sv1_wire`, `fuzz_sv1_method_parsers`)
/// to construct random JSON inputs that exercise `serde_json::from_value`
/// and the `TryFrom` parsers.
#[allow(dead_code)]
pub fn gen_json_value(u: &mut Unstructured<'_>, depth: u8) -> arbitrary::Result<Value> {
    if depth == 0 {
        return Ok(Value::Null);
    }
    Ok(match u.int_in_range(0..=7)? {
        0 => Value::Null,
        1 => Value::Bool(u.arbitrary()?),
        2 => {
            let n: i64 = u.arbitrary()?;
            Value::Number(serde_json::Number::from(n))
        }
        3 => {
            let n: f64 = u.arbitrary()?;
            serde_json::Number::from_f64(n)
                .map(Value::Number)
                .unwrap_or(Value::Null)
        }
        4 => Value::String(u.arbitrary()?),
        5 => {
            let len = u.int_in_range(0..=3)?;
            let mut arr = Vec::with_capacity(len);
            for _ in 0..len {
                arr.push(gen_json_value(u, depth.saturating_sub(1))?);
            }
            Value::Array(arr)
        }
        6 | 7 | _ => {
            let len = u.int_in_range(0..=3)?;
            let mut map = serde_json::Map::new();
            for _ in 0..len {
                let key: String = u.arbitrary()?;
                let val = gen_json_value(u, depth.saturating_sub(1))?;
                map.insert(key, val);
            }
            Value::Object(map)
        }
    })
}

/// Shared oracle for a parsed Sv2 message payload.
///
/// Returns `true` when `parse_message_frame_with_tlvs` succeeds and every
/// invariant below holds; returns `false` when parsing fails (which is expected
/// for arbitrary input). Panics indicate a real bug.
#[allow(dead_code)]
pub fn check_parsed_message(
    header: framing_sv2::header::Header,
    payload: &mut [u8],
    canonical_payload: Option<&[u8]>,
    negotiated_extensions: &[u16],
) -> bool {
    use binary_sv2::GetSize;
    use codec_sv2::Encoder;
    use framing_sv2::framing::MessageFrame;
    use parsers_sv2::{parse_message_frame_with_tlvs, AnyMessageOwned, IsSv2Message, Tlv, TlvList};

    let payload_length = payload.len();
    assert_eq!(
        header.payload_length(),
        payload_length,
        "decoded frame header declares {} payload bytes, but the frame carries {payload_length}",
        header.payload_length()
    );

    let payload_snapshot = payload.to_vec();
    let (message, tlvs) = match parse_message_frame_with_tlvs(header, payload, negotiated_extensions)
    {
        Ok(parsed) => parsed,
        Err(_) => return false,
    };

    let message_size = message.get_size();
    assert!(
        message_size <= payload_length,
        "{} consumed {message_size} bytes from a {payload_length}-byte payload",
        message.message_type()
    );

    // Any panic here is a finding: Display must not trust the decoded values.
    let _ = message.to_string();

    let message_type = message.message_type();
    let extension_type = message.extension_type();
    let channel_bit = message.channel_bit();

    if let Some(tlvs) = &tlvs {
        assert!(!tlvs.is_empty(), "TLV extraction returned an empty list");
        for tlv in tlvs {
            assert_eq!(
                usize::from(tlv.length),
                tlv.value.len(),
                "TLV length {} disagrees with its {} value bytes",
                tlv.length,
                tlv.value.len()
            );
            assert!(
                negotiated_extensions.contains(&tlv.r#type.extension_type),
                "TLV extension type 0x{:04x} was not negotiated",
                tlv.r#type.extension_type
            );

            let encoded = tlv.encode().expect("a decoded TLV must encode again");
            let decoded = Tlv::decode(&encoded).expect("an encoded TLV must decode again");
            assert_eq!(decoded, *tlv, "TLV encode/decode is not stable");
        }
    }

    // The parser splits the payload with `message.get_size()`. Repeating that
    // split here catches a size that disagrees with what the message consumed.
    let tlv_tail = &payload_snapshot[message_size..];
    let re_extracted = TlvList::from_bytes(tlv_tail).for_extensions(negotiated_extensions);
    match &tlvs {
        Some(tlvs) => assert_eq!(
            tlvs, &re_extracted,
            "TLV extraction differs from re-extracting the payload tail"
        ),
        None => assert!(
            re_extracted.is_empty(),
            "TLV extraction returned None for a payload tail containing {} TLVs",
            re_extracted.len()
        ),
    }

    let owned = message.into_owned();

    // Rebuilding a frame with its TLVs is only meaningful for standard
    // messages: `build_frame_bytes_with_tlvs` derives the header extension
    // type from the channel bit alone.
    if extension_type == 0 {
        if let Some(tlvs) = &tlvs {
            let tlv_bytes: usize = tlvs.iter().map(|tlv| 5 + tlv.value.len()).sum();
            if message_size + tlv_bytes <= framing_sv2::SV2_FRAME_MAX_PAYLOAD_SIZE {
                let list = TlvList::from_slice(tlvs).expect("decoded TLVs must rebuild");

                let rebuilt = list
                    .build_frame_bytes_with_tlvs(owned.clone())
                    .expect("a frame with its TLVs must rebuild");
                let rebuilt_header = framing_sv2::header::Header::from_bytes(&rebuilt)
                    .expect("the rebuilt frame must have a header");
                let mut rebuilt_payload = rebuilt[framing_sv2::SV2_FRAME_HEADER_SIZE..].to_vec();
                let (rebuilt_message, rebuilt_tlvs) = parse_message_frame_with_tlvs(
                    rebuilt_header,
                    &mut rebuilt_payload,
                    negotiated_extensions,
                )
                .expect("the rebuilt frame must parse");

                assert_eq!(
                    rebuilt_message.get_size(),
                    message_size,
                    "the rebuilt frame changed the message size"
                );
                assert_eq!(
                    rebuilt_message.message_type(),
                    message_type,
                    "the rebuilt frame changed the message type"
                );
                assert_eq!(
                    rebuilt_message.extension_type(),
                    extension_type,
                    "the rebuilt frame changed the extension type"
                );
                assert_eq!(
                    rebuilt_message.channel_bit(),
                    channel_bit,
                    "the rebuilt frame changed the channel bit"
                );
                assert_eq!(
                    rebuilt_tlvs.as_deref(),
                    Some(tlvs.as_slice()),
                    "the rebuilt frame changed its TLVs"
                );
            }
        }
    }

    let frame = MessageFrame::<AnyMessageOwned>::try_from(owned)
        .expect("a parsed message must fit in an Sv2 frame");

    let canonical_header = frame.header();
    assert_eq!(
        canonical_header.msg_type(),
        message_type,
        "the rebuilt header has the wrong message type"
    );
    assert_eq!(
        canonical_header.ext_type_without_channel_msg(),
        extension_type,
        "the rebuilt header has the wrong extension type"
    );
    assert_eq!(
        canonical_header.channel_msg(),
        channel_bit,
        "the rebuilt header has the wrong channel bit"
    );
    assert_eq!(
        canonical_header.payload_length(),
        message_size,
        "the rebuilt header has the wrong payload length"
    );

    let mut encoder = Encoder::new();
    let encoded = encoder
        .encode(frame)
        .expect("the encoder must accept a frame built from a parsed message");
    let encoded = encoded.as_ref();
    assert_eq!(
        encoded.len(),
        framing_sv2::SV2_FRAME_HEADER_SIZE + message_size,
        "the encoder wrote {} bytes for a {message_size}-byte message",
        encoded.len()
    );

    if let Some(expected) = canonical_payload {
        assert_eq!(
            &encoded[framing_sv2::SV2_FRAME_HEADER_SIZE..],
            expected,
            "a generated payload did not survive the pipeline"
        );
    }

    let reparsed_header = framing_sv2::header::Header::from_bytes(encoded)
        .expect("the encoded frame must have a header");
    let mut reparsed_payload = encoded[framing_sv2::SV2_FRAME_HEADER_SIZE..].to_vec();
    let (reparsed, reparsed_tlvs) = parse_message_frame_with_tlvs(
        reparsed_header,
        &mut reparsed_payload,
        negotiated_extensions,
    )
    .expect("a re-encoded frame must parse");
    assert!(
        reparsed_tlvs.is_none(),
        "re-encoding a bare message produced a TLV tail"
    );
    assert_eq!(
        reparsed.get_size(),
        message_size,
        "re-encoding changed the message size"
    );
    assert_eq!(
        reparsed.message_type(),
        message_type,
        "re-encoding changed the message type"
    );
    assert_eq!(
        reparsed.extension_type(),
        extension_type,
        "re-encoding changed the extension type"
    );
    assert_eq!(
        reparsed.channel_bit(),
        channel_bit,
        "re-encoding changed the channel bit"
    );

    let reparsed_owned = reparsed.into_owned();
    let reparsed_frame = MessageFrame::<AnyMessageOwned>::try_from(reparsed_owned)
        .expect("a reparsed message must fit in an Sv2 frame");
    let mut second_encoder = Encoder::new();
    let re_encoded = second_encoder
        .encode(reparsed_frame)
        .expect("the encoder must accept a reparsed frame");
    assert_eq!(
        re_encoded.as_ref(),
        encoded,
        "re-encoding a parsed message is not byte-identical"
    );

    true
}
